const s = wb.getWorksheet('Q');
const src = s.getRange('A3:E37').getValues();
const blocks = [];
for (let i = 0; i < 35; i += 5) blocks.push({ rows: src.slice(i, i + 5), days: src[i + 4][4], at: i });
blocks.sort((a, b) => (b.days - a.days) || (a.at - b.at));
s.getRange('A3:E37').setValues(blocks.flatMap(b => b.rows));
const a = s.getRange('A3:F37').getValues(), e = s.getRange('I3:N37').getValues();
let diffs = [];
for (let r = 0; r < 35; r++) for (let c = 0; c < 6; c++) { const x = a[r][c] ?? '', y = e[r][c] ?? ''; if (x !== y) diffs.push([r + 3, c, x, y]); }
log(blocks.map(b => b.rows[0][0] + ':' + b.days).join(', '));
log('diffs vs expected', diffs.length, JSON.stringify(diffs.slice(0, 20)));
wb.getRange('Q!A1:F37')

